INSERT INTO public.reception_quiz (mavzu, test_id, question_text, option_text, option_image, is_correct) VALUES ('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'A) Mehmonni faqat ro‘yxatdan o‘tkazish va kalit berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/IMG_4318.PNG', false),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'B) Mehmon bilan ilk aloqa o‘rnatib, ishonch va ijobiy taassurot yaratish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.b.png', true),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'C) Mehmonxona ichki hujjatlari bilan ishlash', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.c.png', false),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'D) Faqat menejer topshiriqlarini bajarish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.d.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'A) Chunki u xizmat narxlarini belgilaydi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.a.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'B) Chunki u mehmon bilan eng ko‘p muloqot qiladigan xodim', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.b.png', true),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'C) Chunki u xonalarni tayyorlaydi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.c.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'D) Chunki faqat u doimo ish bilan band bo‘ladi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.d.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'A) Mehmon murojaatini diqqat bilan eshitish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.a.png', true),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'B) Mehmon oldida shaxsiy telefon bilan shug‘ullanish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.b.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'C) Mehmonni kutishga va qaror qilishga majbur qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.c.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'D) Ikkinchi darajali muammolarni e’tiborsiz qoldirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.d.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'A) Qoidalarni qat’iy aytib, suhbatni tez tugatish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.a.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'B) Mehmonni boshqa kerakli bo‘limga yuborish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.b.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'C) Xotirjam, hurmat bilan eshitib, yechim izlash va taqdim etish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.c.png', true),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'D) Javob bermasdan menejerni kutish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.d.png', false),('1-mavzu', '5-test', 'Reseption xodimining professional xatti-harakati qaysi holatda to‘g‘ri aks etadi?', 'A) Mehmon gapirayotganda tezroq hujjat ishlarini hal etish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.5.a.png', false),('1-mavzu', '5-test', 'Reseption xodimining professional xatti-harakati qaysi holatda to‘g‘ri aks etadi?', 'B) Mehmon bilan ko‘z orqali muloqotni saqlab, diqqat bilan tinglash', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.5.b.png', true),('1-mavzu', '5-test', 'Reseption xodimining professional xatti-harakati qaysi holatda to‘g‘ri aks etadi?', 'C) Suhbat paytida charchamaslikka urinish va buni ko‘rsatish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.5.c.png', false),('1-mavzu', '5-test', 'Reseption xodimining professional xatti-harakati qaysi holatda to‘g‘ri aks etadi?', 'D) Mehmon savoliga qisqa javob berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.5.d.png', false),('1-mavzu', '6-test', 'Quyidagi fikrlardan qaysi biri reseption xodimining rolini eng aniq ifodalaydi?', 'A) Reseption – faqat texnik xizmat ko‘rsatish joyi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.6.a.png', false),('1-mavzu', '6-test', 'Quyidagi fikrlardan qaysi biri reseption xodimining rolini eng aniq ifodalaydi?', 'B) Reseption xodimi mehmon va mehmonxona o‘rtasidagi asosiy aloqa bo‘g‘ini', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.6.b.png', true),('1-mavzu', '6-test', 'Quyidagi fikrlardan qaysi biri reseption xodimining rolini eng aniq ifodalaydi?', 'C) Reseption faqat hujjatlar bilan shug‘ullanadi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.6.c.png', false),('1-mavzu', '6-test', 'Quyidagi fikrlardan qaysi biri reseption xodimining rolini eng aniq ifodalaydi?', 'D) Reseption xodimi faqat bandlikni nazorat qiladi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.6.d.png', false),('2-mavzu', '1-test', 'Mehmon reseption hududiga yaqinlashdi. Reseption xodimining eng to‘g‘ri birinchi harakati qaysi?', 'A) Hujjatlar bilan band bo‘lib, ishini davom ettirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.1.a.png', false),('2-mavzu', '1-test', 'Mehmon reseption hududiga yaqinlashdi. Reseption xodimining eng to‘g‘ri birinchi harakati qaysi?', 'B) Ko‘z bilan aloqa o‘rnatib, yengil tabassum bilan mehmonni qarshi olish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.1.b.png', true),('2-mavzu', '1-test', 'Mehmon reseption hududiga yaqinlashdi. Reseption xodimining eng to‘g‘ri birinchi harakati qaysi?', 'C) Mehmon kelguncha kompyuterdagi vazifalarini yakunlash', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.1.c.png', false),('2-mavzu', '1-test', 'Mehmon reseption hududiga yaqinlashdi. Reseption xodimining eng to‘g‘ri birinchi harakati qaysi?', 'D) Mehmon gap boshlaguncha kutish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.1.d.png', false),('2-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri mehmonni kutib olish standartlariga mos kelmaydi?', 'A) Tashqi ko‘rinish ozoda va tartibli bo‘lishi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.2.a.png', false),('2-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri mehmonni kutib olish standartlariga mos kelmaydi?', 'B) Mehmonni kutib olishda muloyim ohangdan foydalanish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.2.b.png', false),('2-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri mehmonni kutib olish standartlariga mos kelmaydi?', 'C) Mehmon oldida shaxsiy telefon orqali mehmon muammolarini tezroq hal qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.2.c.png', true),('2-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri mehmonni kutib olish standartlariga mos kelmaydi?', 'D) Yordam taklif qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.2.d.png', false),('2-mavzu', '3-test', 'Mehmon reseption oldida bir necha soniya kutib qoldi. Bu holatda reseption xodimi nima qilishi zarur?', 'A) Mehmon o‘zi murojaat qilguncha kutish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.3.a.png', false),('2-mavzu', '3-test', 'Mehmon reseption oldida bir necha soniya kutib qoldi. Bu holatda reseption xodimi nima qilishi zarur?', 'B) Kutish sababini qisqacha tushuntirib, e’tibor qaratish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.3.b.png', true),('2-mavzu', '3-test', 'Mehmon reseption oldida bir necha soniya kutib qoldi. Bu holatda reseption xodimi nima qilishi zarur?', 'C) Hech qanday munosabat bildirmaslik', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.3.c.png', false),('2-mavzu', '3-test', 'Mehmon reseption oldida bir necha soniya kutib qoldi. Bu holatda reseption xodimi nima qilishi zarur?', 'D) Boshqa mehmonlar bilan suhbatni davom ettirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.3.d.png', false),('2-mavzu', '4-test', 'Mehmonni kutib olishda nutq qanday bo‘lishi kerak?', 'A) Juda uzun va batafsil', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.4.a.png', false),('2-mavzu', '4-test', 'Mehmonni kutib olishda nutq qanday bo‘lishi kerak?', 'B) Rasmiy ohangda', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.4.b.png', false),('2-mavzu', '4-test', 'Mehmonni kutib olishda nutq qanday bo‘lishi kerak?', 'C) Qisqa, aniq va muloyim', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.4.c.png', true),('2-mavzu', '4-test', 'Mehmonni kutib olishda nutq qanday bo‘lishi kerak?', 'D) Norasmiy va erkin', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.4.d.png', false),('2-mavzu', '5-test', 'Quyidagi qaysi xatti-harakat mehmon uchun ijobiy birinchi taassurot uyg‘otadi?', 'A) Ko‘z aloqasidan qochib, pastga qarash va andishali bo‘lish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.5.a.png', false),('2-mavzu', '5-test', 'Quyidagi qaysi xatti-harakat mehmon uchun ijobiy birinchi taassurot uyg‘otadi?', 'B) Charchagan yuz ifodasi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.5.b.png', false),('2-mavzu', '5-test', 'Quyidagi qaysi xatti-harakat mehmon uchun ijobiy birinchi taassurot uyg‘otadi?', 'C) Tik holat, ochiq yuz va e’tibor', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.5.c.png', true),('2-mavzu', '5-test', 'Quyidagi qaysi xatti-harakat mehmon uchun ijobiy birinchi taassurot uyg‘otadi?', 'D) Shoshilinch va beparvo munosabat', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.5.d.png', false),('2-mavzu', '6-test', 'Mehmonni kutib olish standartlariga rioya qilinmasa, bu nimaga olib kelishi mumkin?', 'A) Mehmon hech qanday farq sezmaydi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.6.a.png', false),('2-mavzu', '6-test', 'Mehmonni kutib olish standartlariga rioya qilinmasa, bu nimaga olib kelishi mumkin?', 'B) Mehmon xizmat sifatidan norozi bo‘lishi ehtimoli ortadi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.6.b.png', true),('2-mavzu', '6-test', 'Mehmonni kutib olish standartlariga rioya qilinmasa, bu nimaga olib kelishi mumkin?', 'C) Faqat ichki tartib buziladi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.6.c.png', false),('2-mavzu', '6-test', 'Mehmonni kutib olish standartlariga rioya qilinmasa, bu nimaga olib kelishi mumkin?', 'D) Bu faqat menejerga ta’sir qiladi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-2/2.6.d.png', false),('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'A) Juda rasmiy va jiddiy', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-a.png', false),('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'B) Qisqa, aniq va muloyim', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-b.png', true);
INSERT INTO public.reception_quiz (mavzu, test_id, question_text, option_text, option_image, is_correct) VALUES ('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'C) Norasmiy va erkin', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-c.png', false),('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'D) Buyruq ohangida va tartibli', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-d.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'A) Muloyim ohangda gapirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-a.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'B) Mehmon gapini bo‘lmasdan eshitish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-b.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'C) Mehmon savoliga tezlik bilan va keskin javob berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-c.png', true),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'D) Aniq va tushunarli iboralar ishlatish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-d.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'A) Noroziligini bildirib qo‘yishi kerak', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-a.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'B) Mehmonni shoshirish va masalani hal etishi kerak', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-b.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'C) Xotirjam ohangda qayta tushuntirishi lozim', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-c.png', true),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'D) Suhbatni to‘xtatish va Ishida davom etgani ma’qul', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-d.png', false),('3-mavzu', '4-test', 'Muloqot davomida ohangning ahamiyati nimada?', 'A) Faqat suhbatni tez tugatish uchun zarur', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-4-a.png', false),('3-mavzu', '4-test', 'Muloqot davomida ohangning ahamiyati nimada?', 'B) Mehmonni hayajonlantirish va bu orqali unga ta’sir o‘tkazish uchun kerak', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-4-b.png', false),('3-mavzu', '4-test', 'Muloqot davomida ohangning ahamiyati nimada?', 'C) Mehmon o‘zini hurmat qilingan his qilishi uchun zarur', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-4-c.png', true),('3-mavzu', '4-test', 'Muloqot davomida ohangning ahamiyati nimada?', 'D) Qoidalarni qat’iy yetkazish uchun darkor', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-4-d.png', false),('3-mavzu', '5-test', 'Quyidagi qaysi ibora reseption xodimi uchun eng professional hisoblanadi?', 'A) “Bilmayman, hoziroq xodimlardan surishtirib kelaman”', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-5-a.png', false),('3-mavzu', '5-test', 'Quyidagi qaysi ibora reseption xodimi uchun eng professional hisoblanadi?', 'B) “Bu mening ishim emas”', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-5-b.png', false),('3-mavzu', '5-test', 'Quyidagi qaysi ibora reseption xodimi uchun eng professional hisoblanadi?', 'C) “Iltimos, bir oz kutib turing, hozir aniqlashtirib beraman”', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-5-c.png', true),('3-mavzu', '5-test', 'Quyidagi qaysi ibora rese